{"file_path":"src/policies.js","content":"/**
 * Policy state machines. Each keeps one independent state per key, exposing
 * `advance(key, tick)` to bring that key's state up to date, `canAllow(key)`
 * to ask whether a request at the current tick would be allowed, and
 * `record(key)` to spend the allowance once every policy on the route agreed.
 *
 * All counting uses BigInt so arbitrarily large capacities, refills and
 * ticks from the limiter file never lose precision.
 */

export class TokenBucket {
  constructor(capacity, refill, per) {
    this.capacity = capacity
    this.refill = refill
    this.per = per
    // Tokens are tracked as `tokens * per`, which stays an exact integer
    // through every refill step since each step adds `refill * elapsed`.
    this.capacityNumerator = capacity * per
    this.states = new Map()
  }

  advance(key, tick) {
    const state = this.states.get(key)
    if (!state) {
      this.states.set(key, { numerator: this.capacityNumerator, lastTick: tick })
      return
    }
    if (tick > state.lastTick) {
      const elapsed = tick - state.lastTick
      let numerator = state.numerator + this.refill * elapsed
      if (numerator > this.capacityNumerator) numerator = this.capacityNumerator
      state.numerator = numerator
      state.lastTick = tick
    }
  }

  canAllow(key) {
    return this.states.get(key).numerator >= this.per
  }

  record(key) {
    this.states.get(key).numerator -= this.per
  }
}

export class SlidingWindow {
  constructor(limit, span) {
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  advance(key, tick) {
    let state = this.states.get(key)
    if (!state) {
      state = { queue: [] }
      this.states.set(key, state)
    }
    const cutoff = tick - this.span
    while (state.queue.length > 0 && state.queue[0] <= cutoff) state.queue.shift()
  }

  canAllow(key) {
    return BigInt(this.states.get(key).queue.length) < this.limit
  }

  record(key) {
    this.states.get(key).queue.push(this.states.get(key).lastTick ?? this._lastTick(key))
  }

  _lastTick(key) {
    return this._pending
  }
}
"}

