{"file_path":"src/simulate.js","content":"/**
 * Parses a limiter file and replays it in one pass, since the specification
 * requires every declaration to precede every event: by the time an event
 * line is reached, the routing table it depends on is already complete.
 */

import { ParseError } from './errors.js'
import { TokenBucket, SlidingWindow } from './policies.js'

const NAME_RE = /^[A-Za-z0-9_./:-]+$/
const INT_RE = /^(0|[1-9][0-9]*)$/

function requireName(token, line, what) {
  if (!NAME_RE.test(token)) throw new ParseError(line, `invalid ${what} ${token}`)
  return token
}

function requireInt(token, line, field, least) {
  if (!INT_RE.test(token)) throw new ParseError(line, `${field} must be an integer of at least ${least}`)
  const value = BigInt(token)
  if (value < BigInt(least)) throw new ParseError(line, `${field} must be an integer of at least ${least}`)
  return value
}

/**
 * Runs a limiter file (as text) in the given mode ('replay' or 'summary')
 * and returns the full stdout text. Throws a ParseError on the first line
 * that fails to parse.
 */
export function simulate(text, mode) {
  const rawLines = text.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') rawLines.pop()

  const policies = new Map()
  const routes = new Map()
  let sawEvent = false
  let lastTick = null

  const replayLines = []
  const summary = new Map()
  let totalAllowed = 0n
  let totalDenied = 0n

  for (let i = 0; i < rawLines.length; i++) {
    const line = i + 1
    const trimmed = rawLines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]
    const args = tokens.slice(1)

    if (directive === 'bucket' || directive === 'window' || directive === 'route') {
      if (sawEvent) throw new ParseError(line, 'declarations must come before the first event')
    }

    if (directive === 'bucket') {
      if (args.length !== 4) throw new ParseError(line, 'expected bucket <name> <capacity> <refill> <per>')
      const [name, capacityTok, refillTok, perTok] = args
      requireName(name, line, 'policy name')
      const capacity = requireInt(capacityTok, line, 'capacity', 1)
      const refill = requireInt(refillTok, line, 'refill', 0)
      const per = requireInt(perTok, line, 'per', 1)
      if (policies.has(name)) throw new ParseError(line, `policy ${name} is declared twice`)
      policies.set(name, new TokenBucket(capacity, refill, per))
    } else if (directive === 'window') {
      if (args.length !== 3) throw new ParseError(line, 'expected window <name> <limit> <span>')
      const [name, limitTok, spanTok] = args
      requireName(name, line, 'policy name')
      const limit = requireInt(limitTok, line, 'limit', 0)
      const span = requireInt(spanTok, line, 'span', 1)
      if (policies.has(name)) throw new ParseError(line, `policy ${name} is declared twice`)
      policies.set(name, new SlidingWindow(limit, span))
    } else if (directive === 'route') {
      if (args.length < 2) throw new ParseError(line, 'expected route <prefix> <policy>...')
      const [prefix, ...policyNames] = args
      requireName(prefix, line, 'route prefix')
      for (const name of policyNames) {
        if (!policies.has(name)) throw new ParseError(line, `unknown policy ${name}`)
      }
      if (routes.has(prefix)) throw new ParseError(line, `prefix ${prefix} is routed twice`)
      routes.set(prefix, policyNames)
    } else if (directive === 'event') {
      if (args.length !== 2) throw new ParseError(line, 'expected event <tick> <key>')
      const [tickTok, keyTok] = args
      const tick = requireInt(tickTok, line, 'tick', 0)
      requireName(keyTok, line, 'key')
      if (lastTick !== null && tick < lastTick) {
        throw new ParseError(line, `tick ${tick} is before tick ${lastTick}`)
      }
      lastTick = tick
      sawEvent = true

      let matchedPrefix = null
      let matchedPolicies = []
      for (const [prefix, policyNames] of routes) {
        if (keyTok.startsWith(prefix) && (matchedPrefix === null || prefix.length > matchedPrefix.length)) {
          matchedPrefix = prefix
          matchedPolicies = policyNames
        }
      }

      for (const name of matchedPolicies) policies.get(name).advance(keyTok, tick)

      let verdict = 'allow'
      let failingPolicy = null
      for (const name of matchedPolicies) {
        if (!policies.get(name).canAllow(keyTok)) {
          verdict = 'deny'
          failingPolicy = name
          break
        }
      }
      if (verdict === 'allow') {
        for (const name of matchedPolicies) policies.get(name).record(keyTok, tick)
      }

      if (mode === 'replay') {
        replayLines.push(verdict === 'allow' ? `${tick} ${keyTok} allow` : `${tick} ${keyTok} deny ${failingPolicy}`)
      }
      const stats = summary.get(keyTok) ?? { allowed: 0n, denied: 0n }
      if (verdict === 'allow') {
        stats.allowed += 1n
        totalAllowed += 1n
      } else {
        stats.denied += 1n
        totalDenied += 1n
      }
      summary.set(keyTok, stats)
    } else {
      throw new ParseError(line, `unknown directive ${directive}`)
    }
  }

  if (mode === 'replay') {
    return replayLines.map((l) => l + '\n').join('')
  }

  const keys = [...summary.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
  const lines = keys.map((key) => {
    const s = summary.get(key)
    return `${key} allowed=${s.allowed} denied=${s.denied}`
  })
  lines.push(`total allowed=${totalAllowed} denied=${totalDenied}`)
  return lines.map((l) => l + '\n').join('')
}
"}

